"""LOCATION CAPABILITY CENSUS DATA (2026-10-06) -- the retained evidence behind the ten location-capability categories.

Not a registry of its own: it is DATA for the one canonical capability owner (`jurisdiction_comparison.location_capability_cells`
-> `production_requirements.jurisdiction_capability_profile` -> `production_fit`). Every record below was recovered from a record
ALREADY retained in this repository (global_inventory_* program records and the jurisdiction comparison profiles); the `record_ref`
names it, and `source_title` / `source_url` / the tier are that record's OWN provenance (no new source was consulted). The tier is the
retained record's confidence tier (almost all DISCOVERY): the sentence is a retained, cited statement, not an independently verified
fact, and it is served as such. A cell with no record here is UNKNOWN (neutral) -- never a mismatch.

Generated from the retained records by a one-off script that verified each quoted sentence is present in the cited record.
"""
from __future__ import annotations

from dataclasses import dataclass

#: census category -> canonical capability token (the SAME tokens the 13 location chips already reach).
LOCATION_CENSUS_CATEGORIES: dict[str, str] = {
    "island_tropical": "tropical_environments",
    "jungle_rainforest": "jungle_environments",
    "desert_arid": "desert_environments",
    "mountains_alpine": "mountain_environments",
    "snow_arctic": "snow_environments",
    "urban_major_city": "urban_environments",
    "small_town_suburban": "small_town_environments",
    "rural_countryside": "rural_environments",
    "forest_woodland": "forest_environments",
    "historic_old_world": "historic_architecture",
}

SUPPORTED = "SUPPORTED"
NOT_SUPPORTED = "NOT_SUPPORTED"
UNKNOWN = "UNKNOWN"


@dataclass(frozen=True)
class LocationCapabilityRecord:
    status: str                 # SUPPORTED (only non-UNKNOWN status stored here; NOT_SUPPORTED is derived from structured fields)
    proposition: str
    source_title: str
    source_url: str
    publisher: str
    checked_or_effective_date: str
    evidence_tier: str
    record_ref: str


def _r(proposition, source_title, source_url, publisher, date, tier, record_ref):
    return LocationCapabilityRecord(SUPPORTED, proposition, source_title, source_url or "", publisher or "", date or "", tier, record_ref)


